$(function(){function e(){let e=window.innerWidth,n=window.innerHeight;document.documentElement.style.setProperty("--vh",`${n}px`),window.addEventListener("resize",()=>{setTimeout(()=>{if(e!=window.innerWidth){let n=window.innerHeight;document.documentElement.style.setProperty("--vh",`${n}px`),e=window.innerWidth}},50)})}e()});